{
  "participants": [
    {
      "login": "pinheadmz",
      "stance": "question",
      "note": "asked whether HEAD needs to be supported at all rather than disallowed"
    }
  ],
  "claims": [
    {
      "id": "c:5872052013",
      "part": 1,
      "type": "suggestion",
      "kind": "approach",
      "text": "Consider not supporting HEAD at all, keeping METHOD NOT ALLOWED for RPC and limiting REST endpoints to GET requests only",
      "quote": "Do you think there is any real benefit to even supporting HEAD? It might make sense for a webserver but I think we can justify not implementing it at all.",
      "clears_with": "answer",
      "status": "answered",
      "status_note": "author explained that responses to HEAD cannot contain a body regardless of status code (even 405), so suppressing it in WriteReply is necessary either way",
      "author_replies": [
        "c:5882250658"
      ],
      "other_replies": [],
      "fix_pushed": false,
      "status_by_id": "c:5882250658",
      "status_by_quote": "I think this change is needed either way, because rejecting HEAD doesn't make the problem go away: a response to a HEAD request can't have a body regardless of its status code."
    }
  ],
  "support": [],
  "waiting_on": [
    {
      "on": "reviewer",
      "what": "pinheadmz to review the author's explanation on why suppressing the body is needed even for 405 responses",
      "id": "c:5882250658"
    }
  ],
  "notes": "azuchi replied to pinheadmz's suggestion, pointing out that RFC 9112 forbids bodies in response to HEAD even on 405 Method Not Allowed error paths, so the fix is required regardless of whether endpoints accept HEAD."
}
